package com.hermes.jarvis;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.hermes.jarvis.core.CustomToolStore;import java.util.List;
public class ToolsActivity extends AppCompatActivity{private CustomToolStore store;private EditText n,d,c;private CheckBox root;private TextView list;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_tools);store=new CustomToolStore(this);n=findViewById(R.id.etToolName);d=findViewById(R.id.etToolDesc);c=findViewById(R.id.etToolCommand);root=findViewById(R.id.cbToolRoot);list=findViewById(R.id.tvToolList);refresh();findViewById(R.id.btnToolSave).setOnClickListener(v->{CustomToolStore.Tool t=new CustomToolStore.Tool();t.name=n.getText().toString().trim();t.description=d.getText().toString().trim();t.command=c.getText().toString().trim();t.requiresRoot=root.isChecked();if(!t.name.isEmpty()&&!t.command.isEmpty()){store.upsert(t);refresh();n.setText("");d.setText("");c.setText("");}});}
private void refresh(){StringBuilder s=new StringBuilder();for(CustomToolStore.Tool t:store.all())s.append("• ").append(t.name).append(" — ").append(t.description).append("\n  ").append(t.command).append(t.requiresRoot?" [ROOT]":"").append("\n\n");list.setText(s.length()==0?"Belum ada custom tool.":s.toString());}}
